from collections import deque
H,W=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  if grid[r][c] and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); pts=[]
   while q:
    x,y=q.pop(); pts.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     a,b=x+dx,y+dy
     if 0<=a<H and 0<=b<W and grid[a][b] and (a,b) not in seen: seen.add((a,b));q.append((a,b))
   comps.append(pts)
print([(min(r for r,c in p), max(r for r,c in p), min(c for r,c in p),max(c for r,c in p),len(p)) for p in comps])

